"""Producer (weights, biases, constant inputs) C export."""

from pathlib import Path

import aidge_core
from aidge_core.export_utils import aidge2c, generate_file

from .. import C_ROOT
from ..export_registry import ExportLibC
from ..node_export import ExportNodeC


@ExportLibC.register(
    "Producer",
    aidge_core.ImplSpec(aidge_core.IOSpec(aidge_core.dtype.any_or_packed_last)),
)
class ProducerC(ExportNodeC):
    def __init__(self, node, mem_info, instance_count):
        super().__init__(node, mem_info)
        self.output = self.operator.get_output(0)
        self.ignore = (
            node.annotations().ignore
            if node.annotations().has_attr("ignore")
            else False
        )
        if instance_count is not None and instance_count > 0:
            self.ignore = True

        # Producer files are generated by ``export`` below.
        self.config_template = ""
        self.forward_template = None
        self.include_list = []
        self.kernels_to_copy = []

    def export(self, export_folder: Path):
        if self.ignore:
            return []

        name = self.attributes["name"]
        out_name = self.attributes["out_name"][0]
        dtype = aidge2c(self.output.dtype)

        header_rel = Path("include") / "parameters" / f"{name}.h"
        source_rel = Path("src") / "parameters" / f"{name}.c"
        (export_folder / header_rel).parent.mkdir(parents=True, exist_ok=True)
        (export_folder / source_rel).parent.mkdir(parents=True, exist_ok=True)

        tensor_host = aidge_core.Tensor()
        tensor_host.to_dtype(self.output.dtype)
        tensor_host.to_backend("cpu")
        tensor_host.copy_from(self.output)
        tensor_host.resize([self.output.size])
        literals = tensor_host.to_cstring()

        generate_file(
            export_folder / header_rel,
            C_ROOT / "templates" / "data" / "producer_header.h.jinja",
            name=out_name,
            dims=self.output.dims,
            dtype=dtype,
            dtype_name=self.output.dtype,
        )
        generate_file(
            export_folder / source_rel,
            C_ROOT / "templates" / "data" / "producer_src.c.jinja",
            name=out_name,
            declaration_path=f"parameters/{name}.h",
            dims=self.output.dims,
            dtype=dtype,
            dtype_name=self.output.dtype,
            literals=literals,
        )

        return [header_rel.as_posix()]

    def forward(self):
        return []
